struct LocalAIView: View {
    private let session = LanguageModelSession(
        instructions: "Du bist ein freundlicher Swift-Lerncoach. Antworte kurz und korrekt."
    )
    @State private var answer = ""
    @State private var isLoading = false

    var body: some View {
        VStack(spacing: 16) {
            Text(answer.isEmpty ? "Noch keine Antwort" : answer)
            Button("Erkläre @State") {
                Task { await askModel() }
            }
            .disabled(isLoading)
        }
        .padding()
    }

    private func askModel() async {
        isLoading = true
        defer { isLoading = false }
        do {
            answer = try await session.respond(to: "Erkläre @State in drei Sätzen.").content
        } catch {
            answer = "Die Antwort konnte nicht erstellt werden."
        }
    }
}

