import FoundationModels

@Generable
struct StudyPlan {
    @Guide(description: "Ein kurzer Titel")
    let title: String

    @Guide(description: "Konkrete Lernschritte", .count(3))
    let steps: [String]

    @Guide(description: "Geschätzte Minuten", .range(5...60))
    let minutes: Int
}

func createPlan() async throws -> StudyPlan {
    let session = LanguageModelSession()
    let response = try await session.respond(
        to: "Erstelle einen Plan zum Lernen von SwiftUI Bindings.",
        generating: StudyPlan.self
    )
    return response.content
}

import FoundationModels
import Observation

struct ChatMessage: Identifiable {
    let id = UUID()
    let role: Role
    var text: String

    enum Role { case user, assistant }
}

@MainActor
@Observable
final class ChatModel {
    private let session = LanguageModelSession(
        instructions: "Antworte hilfreich, knapp und auf Deutsch."
    )
    var messages: [ChatMessage] = []
    var isResponding = false

    func send(_ prompt: String) async {
        guard !prompt.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        messages.append(ChatMessage(role: .user, text: prompt))
        let answerID = UUID()
        messages.append(ChatMessage(id: answerID, role: .assistant, text: ""))
        isResponding = true
        defer { isResponding = false }

        do {
            for try await partial in session.streamResponse(to: prompt) {
                guard let index = messages.firstIndex(where: { $0.id == answerID }) else { return }
                messages[index].text = partial.content
            }
        } catch {
            guard let index = messages.firstIndex(where: { $0.id == answerID }) else { return }
            messages[index].text = "Antwort fehlgeschlagen."
        }
    }
}

import SwiftUI

struct ChatScreen: View {
    @State private var model = ChatModel()
    @State private var draft = ""

    var body: some View {
        ScrollView {
            LazyVStack(spacing: 12) {
                ForEach(model.messages) { message in
                    Text(message.text)
                        .padding(12)
                        .background(
                            message.role == .user ? Color.accentColor : Color.secondary.opacity(0.15),
                            in: .rect(cornerRadius: 18)
                        )
                        .frame(
                            maxWidth: .infinity,
                            alignment: message.role == .user ? .trailing : .leading
                        )
                }
            }
            .padding()
        }
        .safeAreaInset(edge: .bottom) {
            HStack {
                TextField("Nachricht", text: $draft)
                    .textFieldStyle(.roundedBorder)
                Button("Senden", systemImage: "arrow.up.circle.fill") {
                    let prompt = draft
                    draft = ""
                    Task { await model.send(prompt) }
                }
                .labelStyle(.iconOnly)
                .disabled(model.isResponding || draft.isEmpty)
            }
            .padding()
            .background(.bar)
        }
    }
}

import FoundationModels

struct SearchNotesTool: Tool {
    let name = "searchNotes"
    let description = "Sucht in freigegebenen Notiztiteln nach einem Begriff."
    let noteTitles: [String]

    @Generable
    struct Arguments {
        @Guide(description: "Suchbegriff für Notiztitel")
        let query: String
    }

    func call(arguments: Arguments) async throws -> [String] {
        noteTitles.filter {
            $0.localizedCaseInsensitiveContains(arguments.query)
        }
    }
}

func makeSession(notes: [String]) -> LanguageModelSession {
    LanguageModelSession(tools: [SearchNotesTool(noteTitles: notes)])
}

