struct ImagePlaygroundExample: View {
    @Environment(\.supportsImagePlayground) private var supportsImagePlayground
    @State private var isPresented = false
    @State private var generatedImageURL: URL?

    var body: some View {
        VStack(spacing: 16) {
            if let generatedImageURL {
                AsyncImage(url: generatedImageURL) { image in
                    image.resizable().scaledToFit()
                } placeholder: {
                    ProgressView()
                }
            }

            Button("Bild erstellen", systemImage: "wand.and.stars") {
                isPresented = true
            }
            .disabled(!supportsImagePlayground)
        }
        .imagePlaygroundSheet(
            isPresented: $isPresented,
            concept: "Ein freundlicher Roboter lernt Swift in einer hellen Bibliothek"
        ) { temporaryURL in
            generatedImageURL = temporaryURL
        }
    }
}

import FoundationModels

protocol TextAssistant: Sendable {
    func answer(_ prompt: String) async throws -> String
}

struct OnDeviceAssistant: TextAssistant {
    func answer(_ prompt: String) async throws -> String {
        let model = SystemLanguageModel.default
        guard model.isAvailable else { throw AssistantError.unavailable }
        return try await LanguageModelSession(model: model).respond(to: prompt).content
    }
}

enum AssistantError: Error {
    case unavailable
}

struct RuleBasedAssistant: TextAssistant {
    func answer(_ prompt: String) async throws -> String {
        "Die lokale KI ist nicht verfügbar. Öffne die Offline-Hilfe für: \(prompt)"
    }
}

import CoreML

func classify(features: MLMultiArray, with model: MLModel) async throws -> MLFeatureProvider {
    let input = try MLDictionaryFeatureProvider(dictionary: [
        "features": MLFeatureValue(multiArray: features)
    ])
    return try await model.prediction(from: input)
}

